# Formal exceptional-point table for P4_SPECIAL_LEMMA (referee-4 lists, unordered-pair coordinates): per polynomial its splitting
# quadratic field (must lie in L = Q(i, sqrt2, sqrt-3, sqrt-7)) and the primes where two exceptional points collide (resultants/discriminants).  # LOCAL-OK: seconds
# CONTROL: the known p=13 collision of the c=1 data (-3/2 = i) is detected again here in t-coordinates; and every discriminant's squarefree
# part must be in the group generated by -1, 2, -3, -7 (else FAIL).
import sympy as sp
sys_ = __import__('sys'); sys_.stdout.reconfigure(encoding='utf-8', errors='replace')
x = sp.symbols('x')
LISTS = {'c=1 (u)': [3*x**2+6*x+4, 2*x**2+5*x+4, 2*x+1, 4*x**2+8*x+5, x+1, 12*x**2+24*x+13, x, x+2],
         'c+d=0 (sigma)': [3*x**2+4, 3*x**2+1, x**2-x+2, x+1, x**2+1, x, x-2, x+2],
         'rep (y0)': [x, x-1, x**2-x+1, x**2+x+1, 3*x**2-3*x+1, 2*x**2-2*x+1, x**2+1, x**2-2*x+2]}
def sqf(n):
    n = sp.Integer(n); s = -1 if n < 0 else 1
    for p, e in sp.factorint(abs(n)).items():
        if e % 2: s *= p
    return s
GEN = {1, -1, 2, -2, 3, -3, 6, -6, 7, -7, 14, -14, 21, -21, 42, -42}
ctl = 13 in sp.factorint(abs(sp.resultant(2*x+3, x**2+1, x))); allin = True; rows = []
for cls, L in LISTS.items():
    bad = set(); fields = []
    for P in L:
        if sp.degree(P, x) == 2:
            d = sp.discriminant(P, x); f = sqf(d); fields.append(f); allin &= f in GEN; bad |= set(sp.factorint(abs(d)))
        bad |= set(sp.factorint(abs(sp.LC(P, x))))
    for i in range(len(L)):
        for j in range(i+1, len(L)):
            r = sp.resultant(L[i], L[j], x)
            if r != 0: bad |= set(sp.factorint(abs(r)))
    rows.append((cls, sorted(set(fields)), sorted(bad)))
print('CONTROL p=13 collision detected:', ctl, '| all quadratic fields inside L:', allin, '->', 'PASS' if ctl and allin else 'FAIL')
for cls, f, b in rows: print('| %-14s | sqfree discriminants %s | collision/leading primes %s |' % (cls, f, b))
